function u(i){if(!i)return"Đã xảy ra lỗi không xác định";if(typeof i=="string")return i;if(i.message){const n=i.message.toLowerCase();return n.includes("network")||n.includes("fetch")?"Lỗi kết nối mạng. Vui lòng kiểm tra kết nối internet của bạn.":n.includes("timeout")?"Yêu cầu quá thời gian chờ. Vui lòng thử lại.":n.includes("401")||n.includes("unauthorized")||n.includes("chưa đăng nhập")?"Phiên đăng nhập đã hết hạn. Vui lòng đăng nhập lại.":n.includes("403")||n.includes("forbidden")||n.includes("không có quyền")?"Bạn không có quyền thực hiện hành động này.":n.includes("404")||n.includes("not found")||n.includes("không tìm thấy")?"Không tìm thấy dữ liệu yêu cầu.":n.includes("500")||n.includes("server error")||n.includes("lỗi server")?"Lỗi máy chủ. Vui lòng thử lại sau hoặc liên hệ quản trị viên.":(n.includes("validation")||n.includes("thiếu")||n.includes("invalid"),i.message)}return i.error?u(i.error):"Đã xảy ra lỗi. Vui lòng thử lại."}function s(i,n){const e=u(i);n&&n.error?n.error(e):(console.error("Error:",i),alert(e))}export{s};
